theme.css:
@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;600;700&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700&display=swap');
/* GDELT Cloud Prefab theme — neon glow + frosted glass overlays.
 *
 * Injected via Basic(custom_css=) on top of Prefab's default stylesheet.
 * Designed to be applied SELECTIVELY (one or two elements per card), not
 * drenched across the whole widget — the Next.js app reserves neon glow
 * for titles and a single accent metric per card. Mirror that here.
 *
 * Apply via css_class="neon-text" / "glass-panel" / "glass-panel--glow"
 * on individual components.
 */

/* Neon text-shadow. Matches .neon-text-azure in nextjs_/app/globals.css. */
.neon-text {
  text-shadow:
    0 0 1px hsla(200 100% 60% / 0.55),
    0 0 8px hsla(200 100% 60% / 0.28);
}

/* Stronger variant for hero titles behind a panel. */
.neon-text--strong {
  text-shadow:
    0 0 1px hsla(200 100% 60% / 0.85),
    0 0 8px hsla(200 100% 60% / 0.55),
    0 0 22px hsla(200 100% 60% / 0.35);
}

/* Frosted-glass panel. Matches .sidebar-frost in nextjs_/app/globals.css. */
.glass-panel {
  background:
    linear-gradient(
      135deg,
      hsla(200 100% 60% / 0.05) 0%,
      hsla(0 0% 100% / 0.04) 50%,
      hsla(200 100% 60% / 0.03) 100%
    );
  backdrop-filter: blur(12px) saturate(150%);
  -webkit-backdrop-filter: blur(12px) saturate(150%);
  box-shadow:
    inset 1px 0 0 hsla(200 100% 60% / 0.18),
    inset 0 1px 0 hsla(0 0% 100% / 0.10);
}

/* Glow-tinted variant — paint a subtle azure edge on hover. */
.glass-panel--glow:hover {
  box-shadow:
    inset 1px 0 0 hsla(200 100% 60% / 0.28),
    inset 0 1px 0 hsla(0 0% 100% / 0.14),
    0 0 22px hsla(200 100% 60% / 0.18);
  transition: box-shadow 220ms ease-out;
}
